import json, re, sys, urllib.parse, http.cookiejar, urllib.request, time, random
import html as html_mod

BASE="https://nomask.ai"
UA="Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"

class S:
    def __init__(self, proxy=None):
        self.cj=http.cookiejar.CookieJar()
        handlers=[urllib.request.HTTPCookieProcessor(self.cj)]
        if proxy: handlers.append(urllib.request.ProxyHandler({"http":proxy,"https":proxy}))
        self.op=urllib.request.build_opener(*handlers)
        self.op.addheaders=[("User-Agent",UA),("Accept-Language","en-US,en;q=0.9")]
        self.tok=None
    def page(self,path):
        p=self.get(path)
        m=re.search(r'<script data-page="app" type="application/json">(.*?)</script>', p, re.S)
        d=json.loads(html_mod.unescape(m.group(1))) if m else {}
        return (d.get("props",{}).get("csrf_token")), d.get("props",{})
    def get(self,path):
        r=self.op.open(BASE+path)
        html=r.read().decode()
        m=re.search(r'csrf-token" content="([^"]+)"',html)
        if m: self.tok=m.group(1)
        return html
    def post(self,path,payload=None):
        data=json.dumps(payload).encode() if payload is not None else b"{}"
        req=urllib.request.Request(BASE+path,data=data,method="POST",headers={
            "Content-Type":"application/json","Accept":"application/json",
            "X-Requested-With":"XMLHttpRequest","X-CSRF-TOKEN":self.tok or "","Referer":BASE+"/giveaway"})
        try:
            r=self.op.open(req)
            return r.status, r.read().decode()
        except urllib.error.HTTPError as e:
            return e.code, e.read().decode()

